     (  '-',    '-',    'S',    '-',    '-',    '-',  '-', '-', '-',    'S'  ));

CONSTANT udp_sedffsr : VitalStateTableType (1 TO 58, 1 TO 10) := ( 
--    NOTIFIER   D      CLK     RN       S      SI    SE   EN   Q(t)   Q(t+1)
     (  'X',    '-',    '-',    '-',    '-',    '-',  '-', '-', '-',    'X'  ),
