LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity AFCSIHCONX4 is

     generic ( 
               XOn          : BOOLEAN := DefCombSpikeXOn;
               MsgOn        : BOOLEAN := DefCombSpikeMsgOn;
               InstancePath : STRING  := "*";
               tipd_A : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tipd_CS : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_A_S : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_S_B_EQ_0_AN_CS_EQ_0 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_S_B_EQ_0_AN_CS_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_S_B_EQ_1_AN_CS_EQ_0 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_S_B_EQ_1_AN_CS_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_S : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_S_A_EQ_0_AN_CS_EQ_0 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_S_A_EQ_0_AN_CS_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_S_A_EQ_1_AN_CS_EQ_0 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_S_A_EQ_1_AN_CS_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_CS_S : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_CS_S_OP_A_EQ_0_AN_B_EQ_0_CP_OR_OP_A_EQ_1_AN_B_EQ_1_CP : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_CS_S_OP_A_EQ_0_AN_B_EQ_1_CP_OR_OP_A_EQ_1_AN_B_EQ_0_CP : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_CO1N : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_CO0N : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_CO1N : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_B_CO0N : VitalDelayType01 := (DefDummyDelay, DefDummyDelay)
              );

     port ( 
            A : in std_ulogic := 'U';
            B : in std_ulogic := 'U';
            CS : in std_ulogic := 'U';
            S : out std_ulogic;
            CO0N : out std_ulogic;
            CO1N : out std_ulogic
            );

     attribute VITAL_LEVEL0 of AFCSIHCONX4 : entity is TRUE;
end AFCSIHCONX4;

architecture behavioral of AFCSIHCONX4 is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;


     SIGNAL A_ipd : std_ulogic := 'X';
     SIGNAL B_ipd : std_ulogic := 'X';
     SIGNAL CS_ipd : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( A_ipd, A, tipd_A );
          VitalWireDelay( B_ipd, B, tipd_B );
          VitalWireDelay( CS_ipd, CS, tipd_CS );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd, CS_ipd)


     -- functionality section variables
     VARIABLE S_zd : std_ulogic;
     VARIABLE CO0N_zd : std_ulogic;
     VARIABLE CO1N_zd : std_ulogic;
     VARIABLE n0 : std_ulogic;
     VARIABLE n1 : std_ulogic;
     VARIABLE n2 : std_ulogic;
     VARIABLE n3 : std_ulogic;
     VARIABLE n4 : std_ulogic;
     VARIABLE n5 : std_ulogic;
     VARIABLE n6 : std_ulogic;
     VARIABLE n7 : std_ulogic;
     VARIABLE n8 : std_ulogic;
     VARIABLE n9 : std_ulogic;
     VARIABLE n10 : std_ulogic;
     VARIABLE n11 : std_ulogic;
     VARIABLE n12 : std_ulogic;
     VARIABLE n13 : std_ulogic;
     VARIABLE n14 : std_ulogic;

     -- path delay section variables
     VARIABLE S_GlitchData : VitalGlitchDataType;
     VARIABLE CO0N_GlitchData : VitalGlitchDataType;
     VARIABLE CO1N_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------

          S_zd := VitalXOR3(A_ipd,B_ipd,CS_ipd);          

          CO0N_zd := VitalNAND2(A_ipd, B_ipd);

          CO1N_zd := VitalNOR2(A_ipd, B_ipd);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => S,
               OutSignalName => "S",
               OutTemp => S_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_B_EQ_0_AN_CS_EQ_0 ,
                             ((To_X01(B_ipd) /= '1') and (To_X01(CS_ipd) /= '1'))),
                      1 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_B_EQ_0_AN_CS_EQ_1 ,
                             ((To_X01(B_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      2 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_B_EQ_1_AN_CS_EQ_0 ,
                             ((To_X01(B_ipd) /= '0') and (To_X01(CS_ipd) /= '1'))),
                      3 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_B_EQ_1_AN_CS_EQ_1 ,
                             ((To_X01(B_ipd) /= '0') and (To_X01(CS_ipd) /= '0'))),
                      4 => ( B_ipd'LAST_EVENT,
                             tpd_B_S_A_EQ_0_AN_CS_EQ_0 ,
                             ((To_X01(A_ipd) /= '1') and (To_X01(CS_ipd) /= '1'))),
                      5 => ( B_ipd'LAST_EVENT,
                             tpd_B_S_A_EQ_0_AN_CS_EQ_1 ,
                             ((To_X01(A_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      6 => ( B_ipd'LAST_EVENT,
                             tpd_B_S_A_EQ_1_AN_CS_EQ_0 ,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CS_ipd) /= '1'))),
                      7 => ( B_ipd'LAST_EVENT,
                             tpd_B_S_A_EQ_1_AN_CS_EQ_1 ,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CS_ipd) /= '0'))),
                      8 => ( CS_ipd'LAST_EVENT,
                             tpd_CS_S_OP_A_EQ_0_AN_B_EQ_0_CP_OR_OP_A_EQ_1_AN_B_EQ_1_CP,
                             (((To_X01(A_ipd) /= '1') and (To_X01(B_ipd) /= '1')) or ((To_X01(A_ipd) /= '0') and (To_X01(B_ipd) /= '0')))),
                      9 => ( CS_ipd'LAST_EVENT,
                             tpd_CS_S_OP_A_EQ_0_AN_B_EQ_1_CP_OR_OP_A_EQ_1_AN_B_EQ_0_CP,
                             (((To_X01(A_ipd) /= '1') and (To_X01(B_ipd) /= '0')) or ((To_X01(A_ipd) /= '0') and (To_X01(B_ipd) /= '1'))))),
               GlitchData => S_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => CO0N,
               OutSignalName => "CO0N",
               OutTemp => CO0N_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_CO0N,
                             TRUE ),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_CO0N,
                             TRUE )),
               GlitchData => CO0N_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => CO1N,
               OutSignalName => "CO1N",
               OutTemp => CO1N_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_CO1N,
                             TRUE ),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_CO1N,
                             TRUE )),
               GlitchData => CO1N_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);


END PROCESS;
end behavioral;

