               tpd_CIN_S_A_EQ_1_AN_CS_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_CIN_S : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_A_CO : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_CIN_CO : VitalDelayType01 := (DefDummyDelay, DefDummyDelay)
              );

     port ( 
            A : in std_ulogic := 'U';
            CIN : in std_ulogic := 'U';
            CS : in std_ulogic := 'U';
            S : out std_ulogic;
            CO : out std_ulogic
            );

     attribute VITAL_LEVEL0 of AHCSHCINX2 : entity is TRUE;
