architecture behavioral of AHCSHCINX2 is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;


     SIGNAL A_ipd : std_ulogic := 'X';
     SIGNAL CIN_ipd : std_ulogic := 'X';
     SIGNAL CS_ipd : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( A_ipd, A, tipd_A );
          VitalWireDelay( CIN_ipd, CIN, tipd_CIN );
          VitalWireDelay( CS_ipd, CS, tipd_CS );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, CIN_ipd, CS_ipd)


     -- functionality section variables
     VARIABLE S_zd : std_ulogic;
     VARIABLE CO_zd : std_ulogic;
     VARIABLE n0 : std_ulogic;
     VARIABLE n1 : std_ulogic;
     VARIABLE n2 : std_ulogic;
     VARIABLE n3 : std_ulogic;
     VARIABLE n4 : std_ulogic;
     VARIABLE n5 : std_ulogic;
     VARIABLE n6 : std_ulogic;
     VARIABLE n7 : std_ulogic;
     VARIABLE n8 : std_ulogic;
     VARIABLE n9 : std_ulogic;
     VARIABLE n10 : std_ulogic;
     VARIABLE n11 : std_ulogic;
     VARIABLE n12 : std_ulogic;
     VARIABLE n13 : std_ulogic;
     VARIABLE n14 : std_ulogic;

     -- path delay section variables
     VARIABLE S_GlitchData : VitalGlitchDataType;
     VARIABLE CO_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------

          n0 := VitalINV(CIN_ipd);

          n1 := VitalINV(CS_ipd);

          n2 := VitalXOR2(A_ipd,n0);

          n3 := VitalAND2(A_ipd,n1);

          n4 := VitalAND2(n2,CS_ipd);

          S_zd := VitalOR2(n4,n3);

          CO_zd := VitalAND2(A_ipd,n0);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => S,
               OutSignalName => "S",
               OutTemp => S_zd,
               Paths => (
                      0 => ( CS_ipd'LAST_EVENT,
                             tpd_CS_S_A_EQ_0_AN_CIN_EQ_0,
                             ((To_X01(A_ipd) /= '1') and (To_X01(CIN_ipd) /= '1'))),
                      1 => ( CS_ipd'LAST_EVENT,
                             tpd_CS_S_A_EQ_1_AN_CIN_EQ_0,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CIN_ipd) /= '1'))),
                      2 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CIN_EQ_0_AN_CS_EQ_1,
                             ((To_X01(CIN_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      3 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CIN_EQ_1_AN_CS_EQ_1,
                             ((To_X01(CIN_ipd) /= '0') and (To_X01(CS_ipd) /= '0'))),
                      4 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CS_EQ_0,
                             (To_X01(CS_ipd) /= '1')),
                      5 => ( CIN_ipd'LAST_EVENT,
                             tpd_CIN_S_A_EQ_0_AN_CS_EQ_1,
                             ((To_X01(A_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      6 => ( CIN_ipd'LAST_EVENT,
                             tpd_CIN_S_A_EQ_1_AN_CS_EQ_1,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CS_ipd) /= '0')))),
               GlitchData => S_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => CO,
               OutSignalName => "CO",
               OutTemp => CO_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_CO,
                             TRUE ),
                      1 => ( CIN_ipd'LAST_EVENT,
                             tpd_CIN_CO,
                             TRUE )),
               GlitchData => CO_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);


END PROCESS;
