                             ((To_X01(A_ipd) /= '1') and (To_X01(CI_ipd) /= '0'))),
                      1 => ( CS_ipd'LAST_EVENT,
                             tpd_CS_S_A_EQ_1_AN_CI_EQ_1,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CI_ipd) /= '0'))),
                      2 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CI_EQ_0_AN_CS_EQ_1,
                             ((To_X01(CI_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      3 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CI_EQ_1_AN_CS_EQ_1,
                             ((To_X01(CI_ipd) /= '0') and (To_X01(CS_ipd) /= '0'))),
                      4 => ( A_ipd'LAST_EVENT,
                             tpd_A_S_CS_EQ_0,
                             (To_X01(CS_ipd) /= '1')),
                      5 => ( CI_ipd'LAST_EVENT,
                             tpd_CI_S_A_EQ_0_AN_CS_EQ_1,
                             ((To_X01(A_ipd) /= '1') and (To_X01(CS_ipd) /= '0'))),
                      6 => ( CI_ipd'LAST_EVENT,
                             tpd_CI_S_A_EQ_1_AN_CS_EQ_1,
                             ((To_X01(A_ipd) /= '0') and (To_X01(CS_ipd) /= '0')))),
               GlitchData => S_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => CON,
               OutSignalName => "CON",
               OutTemp => CON_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_CON,
                             TRUE ),
                      1 => ( CI_ipd'LAST_EVENT,
                             tpd_CI_CON,
                             TRUE )),
               GlitchData => CON_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);


END PROCESS;
end behavioral;

