LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity ANTENNA is

     generic ( 
               XOn          : BOOLEAN := DefCombSpikeXOn;
               MsgOn        : BOOLEAN := DefCombSpikeMsgOn;
               InstancePath : STRING  := "*";
               tipd_A : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_A_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_B_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay)
             );

     port ( SIGNAL A : in std_ulogic := 'U');

     attribute VITAL_LEVEL0 of ANTENNA : entity is TRUE;
end ANTENNA;


architecture behavioral of ANTENNA is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

-------------------------------------------
-------------------------------------------
--
--  This model is for a cell that has no
--  logical function.  VITAL produces many
--  warnings for an empty model.  Enough
--  functionality was added to the model
--  so that no warnings are generated.
--
-------------------------------------------
-------------------------------------------


     SIGNAL Y : std_ulogic;         -- This was an output port
     SIGNAL B : std_ulogic := '1';  -- This was an input port
     SIGNAL A_ipd : std_ulogic := 'X';
     SIGNAL B_ipd : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( A_ipd, A, tipd_A );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd)

     -- functionality section variables
     VARIABLE Y_zd : std_ulogic;
     VARIABLE n0 : std_ulogic;
     VARIABLE n1 : std_ulogic;
    

     -- path delay section variables
     VARIABLE Y_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
	  -- Add some functionality even though it really
	  -- does nothing in this model.

          Y_zd := VitalNAND2(A_ipd, B_ipd);

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y,
                             TRUE ),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE )),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
