LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity AO2B2BXL is

     generic ( 
               XOn          : BOOLEAN := DefCombSpikeXOn;
               MsgOn        : BOOLEAN := DefCombSpikeMsgOn;
               InstancePath : STRING  := "*";
               tipd_A0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_A0_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tipd_A1N : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_A1N_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tipd_B0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_B0_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tipd_B1N : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_B1N_Y : VitalDelayType01 := (DefDummyDelay, DefDummyDelay)
             );

     port ( Y : out std_ulogic;
            A0 : in std_ulogic := 'U';
            A1N : in std_ulogic := 'U';
            B0 : in std_ulogic := 'U';
            B1N : in std_ulogic := 'U'
          );

     attribute VITAL_LEVEL0 of AO2B2BXL : entity is TRUE;
end AO2B2BXL;

architecture behavioral of AO2B2BXL is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

     SIGNAL A0_ipd : std_ulogic := 'X';
     SIGNAL A1N_ipd : std_ulogic := 'X';
     SIGNAL B0_ipd : std_ulogic := 'X';
     SIGNAL B1N_ipd : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( A0_ipd, A0, tipd_A0 );
          VitalWireDelay( A1N_ipd, A1N, tipd_A1N );
          VitalWireDelay( B0_ipd, B0, tipd_B0 );
          VitalWireDelay( B1N_ipd, B1N, tipd_B1N );
END BLOCK;

VITALBehavior : PROCESS (A0_ipd, A1N_ipd, B0_ipd, B1N_ipd)


     -- functionality section variables
     VARIABLE outA : std_ulogic;
     VARIABLE outB : std_ulogic;
     VARIABLE outC : std_ulogic;
     VARIABLE outD : std_ulogic;
     VARIABLE outA1 : std_ulogic;
     VARIABLE outB1 : std_ulogic;
     VARIABLE outC1 : std_ulogic;
     VARIABLE outD1 : std_ulogic;
     VARIABLE Y_zd : std_ulogic;

     -- path delay section variables
     VARIABLE Y_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------

          outA1 := VitalINV(A1N_ipd);

          outB1 := VitalINV(B1N_ipd);

          outA := VitalAND2(A0_ipd, outA1);

          outB := VitalAND2(B0_ipd, outB1);

          Y_zd := VitalOR2(outA, outB);

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A0_ipd'LAST_EVENT,
                             tpd_A0_Y,
                             TRUE ),
                      1 => ( A1N_ipd'LAST_EVENT,
                             tpd_A1N_Y,
                             TRUE ),
                      2 => ( B0_ipd'LAST_EVENT,
                             tpd_B0_Y,
                             TRUE ),
                      3 => ( B1N_ipd'LAST_EVENT,
                             tpd_B1N_Y,
                             TRUE )),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
