     port ( 
            D : in std_ulogic := 'U';
            CK : in std_ulogic := 'U';
            SN : in std_ulogic := 'U';
            RN : in std_ulogic := 'U';
            QN : out std_ulogic;
            Q : out std_ulogic
          );

