                        Tviol_SN_RN OR 
                        Tviol_RN_SN OR 
                        Tviol_D_CK OR 
                        Tviol_SN_CK OR 
                        PWviol_SN_negedge OR 
                        Tviol_RN_CK OR 
                        PWviol_RN_negedge OR
                        PWviol_CK  
                       );

          SNx_dly := SN_dly;

          RNx_dly := RN_dly;

          intclk := VitalBUF(CK_dly);

 
