                           DataIn => (NOTIFIER,D_dly,intclk,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_dff_n0 );

          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );
 
          flag := VitalAND2(SNx_dly,RNx_dly);

          QN_zd := VitalINV( n0 );


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
