     VARIABLE Tviol_SN_RN : std_ulogic := '0';
     VARIABLE TimeMarker_SN_RN : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE Tviol_RN_SN : std_ulogic := '0';
     VARIABLE TimeMarker_RN_SN : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE PWviol_CK : std_ulogic := '0';
     VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

     -- functionality section variables
     VARIABLE n0 : std_ulogic;
     VARIABLE intclk : std_ulogic;
     VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
     VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
     VARIABLE Q_zd : std_ulogic;
     VARIABLE flag : std_ulogic;
     VARIABLE NOTIFIER : std_ulogic := '0';

     -- path delay section variables
     VARIABLE Q_GlitchData : VitalGlitchDataType;
     VARIABLE RNx_dly : std_ulogic := '1';
     VARIABLE SNx_dly : std_ulogic := '1';

     BEGIN
          ---------------------------------------------------
          -- Timing checks section
          ---------------------------------------------------
          IF (TimingChecksOn) THEN

               VitalSetupHoldCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   RefSignal      => SN_dly,
                   RefSignalName  => "SN",
                   SetupHigh      => 0 ps,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_RN_SN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   TimingData     => TimeMarker_RN_SN,
                   Violation      => Tviol_RN_SN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   RefSignal      => RN_dly,
                   RefSignalName  => "RN",
                   SetupHigh      => 0 ps,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_SN_RN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   TimingData     => TimeMarker_SN_RN,
                   Violation      => Tviol_SN_RN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );


               VitalSetupHoldCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_RN_CK_posedge_posedge,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_RN_CK_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   TimingData     => TimeMarker_RN_CK,
                   Violation      => Tviol_RN_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );


               VitalSetupHoldCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_SN_CK_posedge_posedge,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_SN_CK_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   TimingData     => TimeMarker_SN_CK,
                   Violation      => Tviol_SN_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );


               VitalSetupHoldCheck (
                   TestSignal     => D_dly,
                   TestSignalName => "D",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_D_CK_posedge_posedge,
                   SetupLow       => tsetup_D_CK_negedge_posedge,
                   HoldHigh       => thold_D_CK_negedge_posedge,
                   HoldLow        => thold_D_CK_posedge_posedge,
                   CheckEnabled   => ( To_X01(flag) ) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   TimingData     => TimeMarker_D_CK,
                   Violation      => Tviol_D_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => CK_dly,
                   TestSignalName => "CK",
                   Period         => 0 ps,
                   PulseWidthHigh => tpw_CK_posedge,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   CheckEnabled   => ( To_X01(flag) ) /= '0',
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_SN_negedge,
                   PeriodData     => PeriodCheckInfo_SN_negedge,
                   Violation      => PWviol_SN_negedge,
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_RN_negedge,
                   PeriodData     => PeriodCheckInfo_RN_negedge,
                   Violation      => PWviol_RN_negedge,
                   HeaderMsg      => InstancePath & "/DFFSRHQX8",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                        Tviol_SN_RN OR 
                        Tviol_RN_SN OR 
                        Tviol_D_CK OR 
                        Tviol_SN_CK OR 
                        PWviol_SN_negedge OR 
                        Tviol_RN_CK OR 
                        PWviol_RN_negedge OR
                        PWviol_CK  
                       );

          SNx_dly := SN_dly;

          RNx_dly := RN_dly;

          intclk := VitalBUF(CK_dly);

 
          VitalStateTable ( StateTable => udp_dff,
                           DataIn => (NOTIFIER,D_dly,intclk,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_dff_n0 );

          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );
 
          flag := VitalAND2(SNx_dly,RNx_dly);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             ( To_X01(flag) ) /= '0' 
                           ),
                      1 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q,
                             TRUE 
                           ),
                      2 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q,
                             TRUE 
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
