                   HeaderMsg      => InstancePath & "/EDFFTRX1",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                       Tviol_D_CK OR 
                       Tviol_RN_CK OR 
                       PWviol_CK OR 
                       Tviol_E_CK );

          RNx_dly := RN_dly;

          SNx_dly := '1';

          VitalStateTable ( StateTable => udp_edfft,
                           DataIn => (NOTIFIER,D_dly,CK_dly,RNx_dly,SNx_dly,E_dly),
