          Dcheck := VitalAND4(SEb,RNx_dly,SNx_dly,E_dly);

          Echeck := VitalAND3(SEb,RNx_dly,SNx_dly);

          flag := VitalAND3(DxorSI,RNx_dly,SNx_dly);

