LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity MDFFHQX8 is

     generic ( 
               tipd_D0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tipd_D1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tisd_D0_CK : VitalDelayType := DefDummyIsd;
               tisd_D1_CK : VitalDelayType := DefDummyIsd;
               tisd_S0_CK : VitalDelayType := DefDummyIsd;
               tpd_CK_Q : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               ticd_CK : VitalDelayType := DefDummyIcd;
               tsetup_D0_CK_posedge_posedge : VitalDelayType := DefDummySetup;
               tsetup_D0_CK_negedge_posedge : VitalDelayType := DefDummySetup;
               thold_D0_CK_posedge_posedge : VitalDelayType := DefDummyHold;
               thold_D0_CK_negedge_posedge : VitalDelayType := DefDummyHold;
               tsetup_D1_CK_posedge_posedge : VitalDelayType := DefDummySetup;
               tsetup_D1_CK_negedge_posedge : VitalDelayType := DefDummySetup;
               thold_D1_CK_posedge_posedge : VitalDelayType := DefDummyHold;
               thold_D1_CK_negedge_posedge : VitalDelayType := DefDummyHold;
               tsetup_S0_CK_posedge_posedge : VitalDelayType := DefDummySetup;
               tsetup_S0_CK_negedge_posedge : VitalDelayType := DefDummySetup;
               thold_S0_CK_posedge_posedge : VitalDelayType := DefDummyHold;
               thold_S0_CK_negedge_posedge : VitalDelayType := DefDummyHold;
               tpw_CK_negedge : VitalDelayType := DefDummyWidth;
               tpw_CK_posedge : VitalDelayType := DefDummyWidth;

               TimingChecksOn : BOOLEAN := false;
               XOn            : BOOLEAN := DefCombSpikeXOn;
               MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
               instancePath   : STRING := "*" );

     port ( 
            D0 : in std_ulogic := 'U';
            D1 : in std_ulogic := 'U';
            S0 : in std_ulogic := 'U';
            CK : in std_ulogic := 'U';
            Q : out std_ulogic
          );

     attribute VITAL_LEVEL0 of MDFFHQX8 : entity is TRUE;
end MDFFHQX8;

architecture behavioral of MDFFHQX8 is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;


     SIGNAL D0_ipd : std_ulogic := 'X';
     SIGNAL D0_dly : std_ulogic := 'X';
     SIGNAL D1_ipd : std_ulogic := 'X';
     SIGNAL D1_dly : std_ulogic := 'X';
     SIGNAL S0_ipd : std_ulogic := 'X';
     SIGNAL S0_dly : std_ulogic := 'X';
     SIGNAL CK_ipd : std_ulogic := 'X';
     SIGNAL CK_dly : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( D0_ipd, D0, tipd_D0 );
          VitalWireDelay( D1_ipd, D1, tipd_D1 );
          VitalWireDelay( S0_ipd, S0, tipd_S0 );
          VitalWireDelay( CK_ipd, CK, tipd_CK );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
          VitalSignalDelay( D0_dly, D0_ipd, tisd_D0_CK );
          VitalSignalDelay( D1_dly, D1_ipd, tisd_D1_CK );
          VitalSignalDelay( S0_dly, S0_ipd, tisd_S0_CK );
          VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
END BLOCK;

VITALBehavior : PROCESS (D0_dly, D1_dly, S0_dly, CK_dly)

     -- timing checks section variables
     VARIABLE Tviol_D0_CK : std_ulogic := '0';
     VARIABLE TimeMarker_D0_CK : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE Tviol_D1_CK : std_ulogic := '0';
     VARIABLE TimeMarker_D1_CK : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE Tviol_S0_CK : std_ulogic := '0';
     VARIABLE TimeMarker_S0_CK : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE Dint : std_ulogic := 'U';
     VARIABLE PWviol_CK : std_ulogic := '0';
     VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

     -- functionality section variables
     VARIABLE n0 : std_ulogic;
     VARIABLE intclk : std_ulogic;
     VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
     VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
     VARIABLE Q_zd : std_ulogic;
     VARIABLE flag : std_ulogic;
     VARIABLE NOTIFIER : std_ulogic := '0';

     -- path delay section variables
     VARIABLE Q_GlitchData : VitalGlitchDataType;
     VARIABLE RNx_dly : std_ulogic := '1';
     VARIABLE SNx_dly : std_ulogic := '1';

     BEGIN
          ---------------------------------------------------
          -- Timing checks section
          ---------------------------------------------------
          IF (TimingChecksOn) THEN

               VitalSetupHoldCheck (
                   TestSignal     => D0_dly,
                   TestSignalName => "D0",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_D0_CK_posedge_posedge,
                   SetupLow       => tsetup_D0_CK_negedge_posedge,
                   HoldHigh       => thold_D0_CK_negedge_posedge,
                   HoldLow        => thold_D0_CK_posedge_posedge,
                   CheckEnabled   => ( To_X01(S0_dly) ) /= '1',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/MDFFHQX8",
                   TimingData     => TimeMarker_D0_CK,
                   Violation      => Tviol_D0_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => D1_dly,
                   TestSignalName => "D1",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_D1_CK_posedge_posedge,
                   SetupLow       => tsetup_D1_CK_negedge_posedge,
                   HoldHigh       => thold_D1_CK_negedge_posedge,
                   HoldLow        => thold_D1_CK_posedge_posedge,
                   CheckEnabled   => ( To_X01(S0_dly) ) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/MDFFHQX8",
                   TimingData     => TimeMarker_D1_CK,
                   Violation      => Tviol_D1_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => S0_dly,
                   TestSignalName => "S0",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_S0_CK_posedge_posedge,
                   SetupLow       => tsetup_S0_CK_negedge_posedge,
                   HoldHigh       => thold_S0_CK_negedge_posedge,
                   HoldLow        => thold_S0_CK_posedge_posedge,
                   CheckEnabled   => ( To_X01(D0_dly xor D1_dly) ) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/MDFFHQX8",
                   TimingData     => TimeMarker_S0_CK,
                   Violation      => Tviol_S0_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => CK_dly,
                   TestSignalName => "CK",
                   Period         => 0 ps,
                   PulseWidthHigh => tpw_CK_posedge,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/MDFFHQX8",
                   CheckEnabled   => ( To_X01(flag) ) /= '0',
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                        Tviol_D0_CK OR 
                        Tviol_D1_CK OR 
                        Tviol_S0_CK OR 
                        PWviol_CK  
                       );

          SNx_dly := '1';

          RNx_dly := '1';

          intclk := VitalBUF(CK_dly);

 
          Dint := VitalMUX2(D1_dly,D0_dly,S0_dly); 
  
          VitalStateTable ( StateTable => udp_dff,
                           DataIn => (NOTIFIER,Dint,intclk,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_dff_n0 );

          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );
 
          flag := VitalAND2(SNx_dly,RNx_dly);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             ( To_X01(flag) ) /= '0' 
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
