                             ((To_X01(S0_ipd) /= '1') and (To_X01(C_ipd) /='0') and (To_X01(A_ipd) /= '1'))),
                      6 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_A_EQ_1_AN_C_EQ_0_AN_S0_EQ_0,
                             ((To_X01(S0_ipd) /= '1') and (To_X01(C_ipd) /='1') and (To_X01(A_ipd) /= '0'))),
                      7 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_B_EQ_0_AN_C_EQ_1_AN_S0_EQ_1,
                             ((To_X01(S0_ipd) /= '0') and (To_X01(C_ipd) /='0') and (To_X01(B_ipd) /= '1'))),
                      8 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_B_EQ_1_AN_C_EQ_0_AN_S0_EQ_1,
                             ((To_X01(S0_ipd) /= '0') and (To_X01(C_ipd) /='1') and (To_X01(B_ipd) /= '0')))),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

