WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( A_ipd, A, tipd_A );
          VitalWireDelay( B_ipd, B, tipd_B );
          VitalWireDelay( C_ipd, C, tipd_C );
          VitalWireDelay( S0_ipd, S0, tipd_S0 );
          VitalWireDelay( S1_ipd, S1, tipd_S1 );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd, C_ipd, S0_ipd, S1_ipd)


     -- functionality section variables
     VARIABLE n0 : std_ulogic;
     VARIABLE Y_zd : std_ulogic;

     -- path delay section variables
     VARIABLE Y_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------

          n0 := VitalMux4((C_ipd & C_ipd & B_ipd & A_ipd),(S1_ipd  & S0_ipd));
     
          Y_zd := VitalBUF( n0 );


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y,
                             TRUE ),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE ),
                      2 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y,
                             TRUE ),
                      3 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_A_EQ_0_AN_B_EQ_1_AN_S1_EQ_0,
                             ((To_X01(S1_ipd) /= '1') and (To_X01(B_ipd) /='0') and (To_X01(A_ipd) /= '1'))),
                      4 => ( S0_ipd'LAST_EVENT,
