                             tpd_S0_Y_A_EQ_0_AN_B_EQ_1_AN_S1_EQ_0,
                             ((To_X01(S1_ipd) /= '1') and (To_X01(B_ipd) /='0') and (To_X01(A_ipd) /= '1'))),
