               tpd_M1_PPN_X2_EQ_0_AN_A_EQ_0_AN_S_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_M0_PPN : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_M0_PPN_X2_EQ_1_AN_A_EQ_1_AN_S_EQ_0 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_M0_PPN_X2_EQ_1_AN_A_EQ_0_AN_S_EQ_1 : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_X2_PPN : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_X2_PPN_OP_M0_EQ_1_AN_A_EQ_1_AN_M1_EQ_0_AN_S_EQ_0_CP_OR_OP_M0_EQ_0_AN_S_EQ_1_AN_M1_EQ_1_AN_A_EQ_0_CP : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);
               tpd_X2_PPN_OP_M0_EQ_1_AN_A_EQ_0_AN_M1_EQ_0_AN_S_EQ_1_CP_OR_OP_M0_EQ_0_AN_S_EQ_0_AN_M1_EQ_1_AN_A_EQ_1_CP : VitalDelayType01 := (DefDummyDelay, DefDummyDelay));

     port ( 
            X2 : in std_ulogic := 'U';
            A : in std_ulogic := 'U';
            S : in std_ulogic := 'U';
            M1 : in std_ulogic := 'U';
            M0 : in std_ulogic := 'U';
            PPN : out std_ulogic);


     attribute VITAL_LEVEL0 of BMXIX4 : entity is TRUE;
end BMXIX4;

architecture behavioral of BMXIX4 is
     attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

     SIGNAL X2_ipd : std_ulogic := 'X';
     SIGNAL A_ipd : std_ulogic := 'X';
     SIGNAL S_ipd : std_ulogic := 'X';
     SIGNAL M1_ipd : std_ulogic := 'X';
     SIGNAL M0_ipd : std_ulogic := 'X';

BEGIN

---------------------------------------------------
-- Input Path Delays
---------------------------------------------------
WIREDELAY : BLOCK
BEGIN
          VitalWireDelay( X2_ipd, X2, tipd_X2 );
          VitalWireDelay( A_ipd, A, tipd_A );
          VitalWireDelay( S_ipd, S, tipd_S );
          VitalWireDelay( M1_ipd, M1, tipd_M1 );
          VitalWireDelay( M0_ipd, M0, tipd_M0 );
END BLOCK;

VITALBehavior : PROCESS (X2_ipd, A_ipd, S_ipd, M1_ipd, M0_ipd)


     -- functionality section variables
     VARIABLE n0 : std_ulogic;
     VARIABLE n1 : std_ulogic;
     VARIABLE n2 : std_ulogic;
     VARIABLE n3 : std_ulogic;
     VARIABLE n4 : std_ulogic;
     VARIABLE PPN_zd : std_ulogic;

     -- path delay section variables
     VARIABLE PPN_GlitchData : VitalGlitchDataType;


     BEGIN

          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------

          n0 := VitalTruthTable ( TruthTable => udp_bmx,
                                  DataIn => (X2_ipd, A_ipd, S_ipd, M1_ipd, M0_ipd));

          PPN_zd := VitalINV( n0 );

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => PPN,
               OutSignalName => "PPN",
               OutTemp => PPN_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
		             tpd_A_PPN_X2_EQ_1_AN_M0_EQ_1,
                             ((To_X01(X2_ipd) /= '0') and (To_X01(M0_ipd) /= '0'))),  
                      1 => ( A_ipd'LAST_EVENT,
		             tpd_A_PPN_X2_EQ_0_AN_M1_EQ_1,
                             ((To_X01(X2_ipd) /= '1') and (To_X01(M1_ipd) /= '0'))),  
                      2 => ( S_ipd'LAST_EVENT,
		             tpd_S_PPN_X2_EQ_1_AN_M0_EQ_0,
                             ((To_X01(X2_ipd) /= '0') and (To_X01(M0_ipd) /= '1'))),  
                      3 => ( S_ipd'LAST_EVENT,
		             tpd_S_PPN_X2_EQ_0_AN_M1_EQ_0,
                             ((To_X01(X2_ipd) /= '1') and (To_X01(M1_ipd) /= '1'))),  
                      4 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_PPN_X2_EQ_0_AN_A_EQ_1_AN_S_EQ_0,
                             ((To_X01(X2_ipd) /= '1') and (To_X01(A_ipd) /= '0') and (To_X01(S_ipd) /= '1'))),  
                      5 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_PPN_X2_EQ_0_AN_A_EQ_0_AN_S_EQ_1,
                             ((To_X01(X2_ipd) /= '1') and (To_X01(A_ipd) /= '1') and (To_X01(S_ipd) /= '0'))),  
                      6 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_PPN_X2_EQ_1_AN_A_EQ_1_AN_S_EQ_0,
                             ((To_X01(X2_ipd) /= '0') and (To_X01(A_ipd) /= '0') and (To_X01(S_ipd) /= '1'))),  
                      7 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_PPN_X2_EQ_1_AN_A_EQ_0_AN_S_EQ_1,
                             ((To_X01(X2_ipd) /= '0') and (To_X01(A_ipd) /= '1') and (To_X01(S_ipd) /= '0'))),  
                      8 => ( X2_ipd'LAST_EVENT,
		             tpd_X2_PPN_OP_M0_EQ_1_AN_A_EQ_1_AN_M1_EQ_0_AN_S_EQ_0_CP_OR_OP_M0_EQ_0_AN_S_EQ_1_AN_M1_EQ_1_AN_A_EQ_0_CP,
                             (((To_X01(M0_ipd) /= '0') and (To_X01(A_ipd) /= '0') and (To_X01(M1_ipd) /= '1') and (To_X01(S_ipd) /= '1')) or ((To_X01(M0_ipd) /= '1') and (To_X01(S_ipd) /= '0') and (To_X01(M1_ipd) /= '0') and (To_X01(A_ipd) /= '1')))),
                      9 => ( X2_ipd'LAST_EVENT,
		             tpd_X2_PPN_OP_M0_EQ_1_AN_A_EQ_0_AN_M1_EQ_0_AN_S_EQ_1_CP_OR_OP_M0_EQ_0_AN_S_EQ_0_AN_M1_EQ_1_AN_A_EQ_1_CP,
                             (((To_X01(M0_ipd) /= '0') and (To_X01(A_ipd) /= '1') and (To_X01(M1_ipd) /= '1') and (To_X01(S_ipd) /= '0')) or ((To_X01(M0_ipd) /= '1') and (To_X01(S_ipd) /= '1') and (To_X01(M1_ipd) /= '0') and (To_X01(A_ipd) /= '0'))))),
               GlitchData => PPN_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);


END PROCESS;
end behavioral;
