          ---------------------------------------------------

          n0 := VitalINV(M1_ipd);

          n1 := VitalINV(M0_ipd);

          n2 := VitalOR2(n0,n1);

          S_zd := VitalNAND2(M2_ipd,n2);
 
          n3 := VitalINV(M2_ipd);

          n4 := VitalOR2(M1_ipd, M0_ipd);

          A_zd := VitalNAND2(n3,n4);

          X2_zd := VitalXNOR2(M1_ipd, M0_ipd);

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => S,
               OutSignalName => "S",
               OutTemp => S_zd,
               Paths => (
                      0 => ( M2_ipd'LAST_EVENT,
		             tpd_M2_S,
                             TRUE),
                      1 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_S,
                             TRUE),
                      2 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_S,
                             TRUE)),
               GlitchData => S_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => A,
               OutSignalName => "A",
               OutTemp => A_zd,
               Paths => (
                      0 => ( M2_ipd'LAST_EVENT,
		             tpd_M2_A,
                             TRUE),
                      1 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_A,
                             TRUE),
                      2 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_A,
                             TRUE)),
               GlitchData => A_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => X2,
               OutSignalName => "X2",
               OutTemp => X2_zd,
               Paths => (
                      0 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_X2_M0_EQ_0,
                             (To_X01(M0_ipd) /= '1')),  
                      1 => ( M1_ipd'LAST_EVENT,
		             tpd_M1_X2_M0_EQ_1,
                             (To_X01(M0_ipd) /= '0')),  
                      2 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_X2_M1_EQ_0,
                             (To_X01(M1_ipd) /= '1')),  
                      3 => ( M0_ipd'LAST_EVENT,
		             tpd_M0_X2_M1_EQ_1,
                             (To_X01(M1_ipd) /= '0'))),  
               GlitchData => X2_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
