                   CheckEnabled   => To_X01(SandR) /= '0',
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                        Tviol_D_CK OR 
                        Tviol_SI_CK OR 
                        Tviol_SE_CK OR 
                        PWviol_CK  
                       );

          SNx_dly := '1';

          RNx_dly := '1';

          intclk := VitalBUF(CK_dly);

          n1 := VitalTruthTable ( TruthTable => udp_mux,
                                  DataIn => (D_dly,SI_dly,SE_dly) );

