          SEb := VitalINV( SE_dly );

          SandRandSEb := VitalAND2(SandR,SEb);

          DxorSD := VitalXOR2(D_dly,SI_dly);

          flag := VitalAND2(DxorSD,SandR);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             To_X01(SandR) /= '0' 
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
