     VARIABLE n1 : std_ulogic;
     VARIABLE Q_zd : std_ulogic;
     VARIABLE RNx_dly : std_ulogic;
     VARIABLE SNx_dly : std_ulogic;
     VARIABLE SandR : std_ulogic;
     VARIABLE SandRandSE : std_ulogic;
