               VitalPeriodPulseCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_RN_negedge,
                   PeriodData     => PeriodCheckInfo_RN_negedge,
                   Violation      => PWviol_RN_negedge,
                   HeaderMsg      => InstancePath & "/SDFFRX1",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                        Tviol_D_CK OR 
                        Tviol_SI_CK OR 
                        Tviol_SE_CK OR 
                        Tviol_RN_CK OR 
                        PWviol_RN_negedge OR
                        PWviol_CK  
                       );

          SNx_dly := '1';

          RNx_dly := RN_dly;

          intclk := VitalBUF(CK_dly);

          n1 := VitalTruthTable ( TruthTable => udp_mux,
                                  DataIn => (D_dly,SI_dly,SE_dly) );

          VitalStateTable ( StateTable => udp_dff,
                           DataIn => (NOTIFIER,n1,intclk,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_dff_n0 );
          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );

          SandR := VitalAND2(SNx_dly,RNx_dly);

          SandRandSE := VitalAND2(SandR,SE_dly);

          SEb := VitalINV( SE_dly );

          SandRandSEb := VitalAND2(SandR,SEb);

          DxorSD := VitalXOR2(D_dly,SI_dly);

          flag := VitalAND2(DxorSD,SandR);

          QN_zd := VitalINV( n0 );


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             To_X01(SandR) /= '0' 
                           ),
                      1 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q,
                             TRUE 
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN,
                             To_X01(SandR) /= '0' 
                           ),
                      1 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN,
                             TRUE 
                           )
                        ),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
