               tipd_SN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
               tpd_SN_Q : VitalDelayType01 := (DefDummyDelay, VitalZeroDelay);
               tsetup_SN_CK_posedge_posedge : VitalDelayType := DefDummySetup;
