               tpd_SN_QN : VitalDelayType01 := (VitalZeroDelay, DefDummyDelay);
               tpd_CK_QN : VitalDelayType01 := (DefDummyDelay, DefDummyDelay);

               TimingChecksOn : BOOLEAN := false;
               XOn : Boolean := DefCombSpikeXOn;
               MsgOn : Boolean := DefCombSpikeMsgOn;
               instancePath : STRING := "*" );

     port ( 
            D : in std_ulogic := 'U';
            SI : in std_ulogic := 'U';
            SE : in std_ulogic := 'U';
            CK : in std_ulogic := 'U';
            SN : in std_ulogic := 'U';
