                    Violation      => Tviol_SN_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => D_dly,
                   TestSignalName => "D",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_D_CK_posedge_posedge,
                   SetupLow       => tsetup_D_CK_negedge_posedge,
                   HoldHigh       => thold_D_CK_negedge_posedge,
                   HoldLow        => thold_D_CK_posedge_posedge,
                   CheckEnabled   => To_X01(SandRandSEb) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/SDFFSQX2",
                   TimingData     => TimeMarker_D_CK,
                   Violation      => Tviol_D_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SI_dly,
