                   Violation      => Tviol_RN_SN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   RefSignal      => RN_dly,
                   RefSignalName  => "RN",
                   SetupHigh      => 0 ps,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_SN_RN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   TimingData     => TimeMarker_SN_RN,
                   Violation      => Tviol_SN_RN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );


                VitalSetupHoldCheck (
                    TestSignal     => RN_dly,
                    TestSignalName => "RN",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_RN_CK_posedge_posedge,
                    SetupLow       => 0 ps,
                    HoldHigh       => 0 ps,
                    HoldLow        => thold_RN_CK_posedge_posedge,
                    CheckEnabled   => TRUE,
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                    TimingData     => TimeMarker_RN_CK,
                    Violation      => Tviol_RN_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => SN_dly,
                    TestSignalName => "SN",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SN_CK_posedge_posedge,
                    SetupLow       => 0 ps,
                    HoldHigh       => 0 ps,
                    HoldLow        => thold_SN_CK_posedge_posedge,
                    CheckEnabled   => TRUE,
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                    TimingData     => TimeMarker_SN_CK,
                    Violation      => Tviol_SN_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => D_dly,
                   TestSignalName => "D",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_D_CK_posedge_posedge,
                   SetupLow       => tsetup_D_CK_negedge_posedge,
                   HoldHigh       => thold_D_CK_negedge_posedge,
                   HoldLow        => thold_D_CK_posedge_posedge,
                   CheckEnabled   => To_X01(SandRandSEb) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   TimingData     => TimeMarker_D_CK,
                   Violation      => Tviol_D_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SI_dly,
                   TestSignalName => "SI",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_SI_CK_posedge_posedge,
                   SetupLow       => tsetup_SI_CK_negedge_posedge,
                   HoldHigh       => thold_SI_CK_negedge_posedge,
                   HoldLow        => thold_SI_CK_posedge_posedge,
                   CheckEnabled   => To_X01(SandRandSE) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   TimingData     => TimeMarker_SI_CK,
                   Violation      => Tviol_SI_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SE_dly,
                   TestSignalName => "SE",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_SE_CK_posedge_posedge,
                   SetupLow       => tsetup_SE_CK_negedge_posedge,
                   HoldHigh       => thold_SE_CK_negedge_posedge,
                   HoldLow        => thold_SE_CK_posedge_posedge,
                   CheckEnabled   => To_X01(flag) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   TimingData     => TimeMarker_SE_CK,
                   Violation      => Tviol_SE_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => CK_dly,
                   TestSignalName => "CK",
                   Period         => 0 ps,
                   PulseWidthHigh => tpw_CK_posedge,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   CheckEnabled   => To_X01(SandR) /= '0',
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_SN_negedge,
                   PeriodData     => PeriodCheckInfo_SN_negedge,
                   Violation      => PWviol_SN_negedge,
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_RN_negedge,
                   PeriodData     => PeriodCheckInfo_RN_negedge,
                   Violation      => PWviol_RN_negedge,
                   HeaderMsg      => InstancePath & "/SDFFSRHQX4",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                        Tviol_D_CK OR 
                        Tviol_SI_CK OR 
                        Tviol_SE_CK OR 
                        Tviol_SN_CK OR 
                        PWviol_SN_negedge OR 
                        Tviol_RN_CK OR 
                        PWviol_RN_negedge OR
                        PWviol_CK  
                       );

          SNx_dly := SN_dly;

          RNx_dly := RN_dly;

          intclk := VitalBUF(CK_dly);

          n1 := VitalTruthTable ( TruthTable => udp_mux,
                                  DataIn => (D_dly,SI_dly,SE_dly) );

          VitalStateTable ( StateTable => udp_dff,
                           DataIn => (NOTIFIER,n1,intclk,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_dff_n0 );
          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );

          SandR := VitalAND2(SNx_dly,RNx_dly);

          SandRandSE := VitalAND2(SandR,SE_dly);

          SEb := VitalINV( SE_dly );

          SandRandSEb := VitalAND2(SandR,SEb);

          DxorSD := VitalXOR2(D_dly,SI_dly);

          flag := VitalAND2(DxorSD,SandR);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             To_X01(SandR) /= '0' 
                           ),
                      1 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q,
                             TRUE 
                           ),
                      2 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q,
                             TRUE 
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
