               instancePath : STRING := "*" );

     port ( 
            D : in std_ulogic := 'U';
            SI : in std_ulogic := 'U';
            SE : in std_ulogic := 'U';
            CK : in std_ulogic := 'U';
            RN : in std_ulogic := 'U';
            QN : out std_ulogic;
            Q : out std_ulogic
          );

     attribute VITAL_LEVEL0 of SDFFTRXL : entity is TRUE;
