                   Violation      => Tviol_SE_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => CK_dly,
                   TestSignalName => "CK",
                   Period         => 0 ps,
                   PulseWidthHigh => tpw_CK_posedge,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/SEDFFXL",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                       Tviol_D_CK OR 
                       Tviol_SI_CK OR 
                       Tviol_SE_CK OR 
                       PWviol_CK OR 
                       Tviol_E_CK );

          RNx_dly := '1';

          SNx_dly := '1';

