               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN,
                             ( To_X01(NoSetReset) ) /= '0' 
                           )
                        ),
