                   Period         => 0 ps,
                   PulseWidthHigh => tpw_CK_posedge,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/SEDFFTRX1",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := ( 
                       Tviol_D_CK OR 
                       Tviol_RN_CK OR 
                       Tviol_SI_CK OR 
                       Tviol_SE_CK OR 
                       PWviol_CK OR 
                       Tviol_E_CK );

          RNx_dly := RN_dly;

          SNx_dly := '1';

          VitalStateTable ( StateTable => udp_sedfft,
                           DataIn => (NOTIFIER,D_dly,CK_dly,RNx_dly,SNx_dly,E_dly,SI_dly,SE_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_sedfft_n0 );
          n0 := n0_vec(1);

          Q_zd := VitalBUF( n0 );

          QN_zd := VitalINV( n0 );

          SEb := VitalINV( SE_dly );

          scan := VitalAND3( SE_dly, RNx_dly, SNx_dly );
 
          DxorSI := VitalXOR2(D_dly, SI_dly);

          Dcheck := VitalAND4(SEb,RNx_dly,SNx_dly,E_dly);

          Echeck := VitalAND3(SEb,RNx_dly,SNx_dly);

          flag := VitalAND3(DxorSI,RNx_dly,SNx_dly);

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q,
                             TRUE
                           )
                        ),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN,
                             TRUE
                           )
                        ),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
