     VARIABLE SandR : std_ulogic;
     VARIABLE SandRandCLK : std_ulogic;
     VARIABLE NOTIFIER : std_ulogic := '0';

     -- path delay section variables
     VARIABLE Q_GlitchData : VitalGlitchDataType;
     VARIABLE QN_GlitchData : VitalGlitchDataType;


     BEGIN
          ---------------------------------------------------
          -- Timing checks section
          ---------------------------------------------------
          IF (TimingChecksOn) THEN

               VitalSetupHoldCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   RefSignal      => SN_dly,
                   RefSignalName  => "SN",
                   SetupHigh      => 0 ps,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_RN_SN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   TimingData     => TimeMarker_RN_SN,
                   Violation      => Tviol_RN_SN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   RefSignal      => RN_dly,
                   RefSignalName  => "RN",
                   SetupHigh      => 0 ps,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_SN_RN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   TimingData     => TimeMarker_SN_RN,
                   Violation      => Tviol_SN_RN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   RefSignal      => GN_dly,
                   RefSignalName  => "GN",
                   SetupHigh      => tsetup_RN_GN_posedge_posedge,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_RN_GN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   TimingData     => TimeMarker_RN_GN,
                   Violation      => Tviol_RN_GN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   RefSignal      => GN_dly,
                   RefSignalName  => "GN",
                   SetupHigh      => tsetup_SN_GN_posedge_posedge,
                   SetupLow       => 0 ps,
                   HoldHigh       => 0 ps,
                   HoldLow        => thold_SN_GN_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   TimingData     => TimeMarker_SN_GN,
                   Violation      => Tviol_SN_GN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => D_dly,
                   TestSignalName => "D",
                   RefSignal      => GN_dly,
                   RefSignalName  => "GN",
                   SetupHigh      => tsetup_D_GN_posedge_posedge,
                   SetupLow       => tsetup_D_GN_negedge_posedge,
                   HoldHigh       => thold_D_GN_negedge_posedge,
                   HoldLow        => thold_D_GN_posedge_posedge,
                   CheckEnabled   => To_X01(SandR) /= '0',
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   TimingData     => TimeMarker_D_GN,
                   Violation      => Tviol_D_GN,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => GN_dly,
                   TestSignalName => "GN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_GN_negedge,
                   PeriodData     => PeriodCheckInfo_GN,
                   Violation      => PWviol_GN,
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   CheckEnabled   => To_X01(SandR) /= '0',
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => SN_dly,
                   TestSignalName => "SN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_SN_negedge,
                   PeriodData     => PeriodCheckInfo_SN_negedge,
                   Violation      => PWviol_SN_negedge,
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => RN_dly,
                   TestSignalName => "RN",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_RN_negedge,
                   PeriodData     => PeriodCheckInfo_RN_negedge,
                   Violation      => PWviol_RN_negedge,
                   HeaderMsg      => InstancePath & "/TLATNSRXL",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := (  
                        Tviol_RN_GN OR  
                        PWviol_RN_negedge OR
                        Tviol_SN_GN OR  
                        PWviol_SN_negedge OR 
                        Tviol_D_GN OR  
                        PWviol_GN  
                      );

          RNx_dly := RN_dly;

          SNx_dly := SN_dly;


          clk_int := VitalBUF( GN_dly );

          clk := VitalINV( GN_dly );

          VitalStateTable ( StateTable => udp_tlat,
                           DataIn => (NOTIFIER,D_dly,clk_int,RNx_dly,SNx_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_tlat_n0 );
          n0 := n0_vec(1);

          QN_zd := VitalINV( n0 );

          Q_zd := VitalBUF( n0 );

          SandR := VitalAND2(SNx_dly,RNx_dly);

          SandRandCLK := VitalAND3(SNx_dly,RNx_dly,clk);


          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( GN_dly'LAST_EVENT,
                             tpd_GN_Q,
                             ( To_X01(SandR) ) /= '0' 
                           ),
                      1 => ( D_dly'LAST_EVENT,
                             tpd_D_Q,
                             ( To_X01(SandRandCLK) ) /= '0' 
                           ),
                      2 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q,
                             TRUE 
                           ),
                      3 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q,
                             TRUE 
                           )),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

          VitalPathDelay01(
               OutSignal => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( GN_dly'LAST_EVENT,
                             tpd_GN_QN,
                             ( To_X01(SandR) ) /= '0' 
                           ),
                      1 => ( D_dly'LAST_EVENT,
                             tpd_D_QN,
                             ( To_X01(SandRandCLK) ) /= '0' 
                           ),
                      2 => ( SN_dly'LAST_EVENT,
                             tpd_SN_QN,
                             TRUE 
                           ),
                      3 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN,
                             TRUE 
                           )),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);

END PROCESS;
end behavioral;
