          VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
          VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
END BLOCK;

VITALBehavior : PROCESS (SE_dly, E_dly, CK_dly)

     -- timing checks section variables
     VARIABLE Tviol_SE_CK : std_ulogic := '0';
     VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE Tviol_E_CK : std_ulogic := '0';
     VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
     VARIABLE PWviol_CK : std_ulogic := '0';
     VARIABLE PeriodCheckInfo_CK_posedge : VitalPeriodDataType;


     -- functionality section variables
     VARIABLE n0 : std_ulogic;
     VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
     VARIABLE PrevData_udp_tlat_n0 : std_logic_vector( 0 TO 4 );
     VARIABLE ECK_zd : std_ulogic;
     VARIABLE xRN_dly : std_ulogic;
     VARIABLE xSN_dly : std_ulogic;
     VARIABLE en : std_ulogic;
     VARIABLE clk : std_ulogic;
     VARIABLE nclk : std_ulogic;
     VARIABLE nn0 : std_ulogic;
     VARIABLE NOTIFIER : std_ulogic := '0';

     -- path delay section variables
     VARIABLE ECK_GlitchData : VitalGlitchDataType;


     BEGIN
          ---------------------------------------------------
          -- Timing checks section
          ---------------------------------------------------
          IF (TimingChecksOn) THEN

               VitalSetupHoldCheck (
                   TestSignal     => E_dly,
                   TestSignalName => "E",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_E_CK_posedge_posedge,
                   SetupLow       => tsetup_E_CK_negedge_posedge,
                   HoldHigh       => thold_E_CK_negedge_posedge,
                   HoldLow        => thold_E_CK_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNTSCAX16",
                   TimingData     => TimeMarker_E_CK,
                   Violation      => Tviol_E_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalSetupHoldCheck (
                   TestSignal     => SE_dly,
                   TestSignalName => "SE",
                   RefSignal      => CK_dly,
                   RefSignalName  => "CK",
                   SetupHigh      => tsetup_SE_CK_posedge_posedge,
                   SetupLow       => tsetup_SE_CK_negedge_posedge,
                   HoldHigh       => thold_SE_CK_negedge_posedge,
                   HoldLow        => thold_SE_CK_posedge_posedge,
                   CheckEnabled   => TRUE,
                   RefTransition  => 'R',
                   HeaderMsg      => InstancePath & "/TLATNTSCAX16",
                   TimingData     => TimeMarker_SE_CK,
                   Violation      => Tviol_SE_CK,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

               VitalPeriodPulseCheck (
                   TestSignal     => CK_dly,
                   TestSignalName => "CK",
                   Period         => 0 ps,
                   PulseWidthHigh => 0 ps,
                   PulseWidthLow  => tpw_CK_negedge,
                   PeriodData     => PeriodCheckInfo_CK_posedge,
                   Violation      => PWviol_CK,
                   HeaderMsg      => InstancePath & "/TLATNTSCAX16",
                   CheckEnabled   => TRUE,
                   XOn            => DefSeqXOn,
                   MsgOn          => DefSeqMsgOn,
                   MsgSeverity    => WARNING );

          END IF;


          ---------------------------------------------------
          -- Functionality section
          ---------------------------------------------------
          NOTIFIER := (  
                        Tviol_SE_CK OR  
                        Tviol_E_CK OR  
                        PWviol_CK  
                      );

          xRN_dly := '1';

          xSN_dly := '1';

          clk := VitalBUF( CK_dly );

          nclk := VitalINV(CK_dly);
          en := VitalOR2(E_dly,SE_dly);

          VitalStateTable ( StateTable => udp_tlat,
                           DataIn => (NOTIFIER,en,clk,xRN_dly,xSN_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_tlat_n0 );
          n0 := n0_vec(1);

          ECK_zd := VitalAND2( n0, clk );

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => ECK,
               OutSignalName => "ECK",
               OutTemp => ECK_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK,
                             TRUE
                           )),
               GlitchData => ECK_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);



END PROCESS;
end behavioral;
