          nclk := VitalINV(CK_dly);
          en := VitalOR2(E_dly,SE_dly);

          VitalStateTable ( StateTable => udp_tlat,
                           DataIn => (NOTIFIER,en,clk,xRN_dly,xSN_dly),
                        NumStates => 1,
                           Result => n0_vec,
                   PreviousDataIn => PrevData_udp_tlat_n0 );
          n0 := n0_vec(1);

          ECK_zd := VitalAND2( n0, clk );

          ---------------------------------------------------
          -- Path delay section
          ---------------------------------------------------
          VitalPathDelay01(
               OutSignal => ECK,
               OutSignalName => "ECK",
               OutTemp => ECK_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK,
                             TRUE
                           )),
               GlitchData => ECK_GlitchData,
               Mode  => OnEvent,
               XOn => XOn,
               MsgOn => MsgOn,
               MsgSeverity => WARNING);



END PROCESS;
end behavioral;
